<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Plus,ArrowLeft,Download,SlidersHorizontal,ChevronUp,ChevronDown} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {defaultPreset,validatePreset,importPreset,exportPreset,promptSlots,type PromptPreset,type PresetAsset,type PresetDefaults} from '../prompt-runtime/preset'
import type {CharacterCard} from './card-format'
const store=useLocal(),rows=ref<Document<PresetAsset>[]>([]),cards=ref<Document<CharacterCard>[]>([]),defaults=ref<Document<PresetDefaults>|null>(null),editing=ref<PromptPreset|null>(null),editingId=ref(''),revision=ref(0),search=ref(''),error=ref(''),busy=ref(false),controller=new AbortController();let disposed=false,epoch=0
const labels:Record<string,string>={description:'角色描述',personality:'性格',scenario:'场景',systemPrompt:'卡片系统提示',exampleMessages:'示例',persona:'用户身份',authorNote:'作者注释',history:'历史',postHistoryInstructions:'后置指令',custom:'自定义'}
const visible=computed(()=>rows.value.filter(row=>row.value.name.toLowerCase().includes(search.value.toLowerCase())))
async function load(){const vault=store.vault;if(!vault)return;const [values,charList,global]=await Promise.all([vault.list<PresetAsset>('settings'),vault.list<CharacterCard>('card'),vault.read<PresetDefaults>('settings:prompt-presets')]);if(disposed||store.vault!==vault)return;rows.value=values.filter(row=>row.value.assetType==='prompt-preset');cards.value=charList;defaults.value=global}
function edit(row?:Document<PresetAsset>){epoch++;editing.value=row?JSON.parse(JSON.stringify(row.value.preset)):defaultPreset();editingId.value=row?.id||'prompt-preset:'+crypto.randomUUID();revision.value=row?.revision||0;error.value=''}
function move(index:number,direction:number){const slots=editing.value!.slots,next=index+direction;if(next<0||next>=slots.length)return;const row=slots.splice(index,1)[0]!;slots.splice(next,0,row)}
function add(){editing.value!.slots.push({id:crypto.randomUUID(),name:'自定义提示',source:'custom',role:'system',text:'',enabled:true})}
async function save(){const vault=store.vault;if(!vault||!editing.value||busy.value)return;busy.value=true;const generation=epoch,id=editingId.value,expected=revision.value,preset=JSON.parse(JSON.stringify(editing.value)) as PromptPreset,value:PresetAsset={assetType:'prompt-preset',name:preset.name,preset},operation=crypto.randomUUID();try{validatePreset(preset);exportPreset(preset);try{await vault.commitBundle(operation,[{kind:'settings',id,expectedRevision:expected,value}],controller.signal)}catch(e){if(controller.signal.aborted)throw e;const receipt=await vault.receipt(operation),saved=receipt?await vault.read(id):null;if(!saved||saved.revision!==expected+1||canonical(saved.value)!==canonical(value))throw e}if(disposed||store.vault!==vault||generation!==epoch)return;if(editing.value&&canonical(editing.value)!==canonical(preset)){revision.value=expected+1;error.value='上一份修改已保存，当前内容还未保存'}else editing.value=null;await load()}catch(e){if(!disposed&&generation===epoch)error.value=(e as Error).message}finally{busy.value=false}}
async function bind(row:Document<PresetAsset>,cardId?:string){const vault=store.vault;if(!vault||busy.value||cardId==='')return;busy.value=true;try{const value:PresetDefaults={defaultPresetId:defaults.value?.value.defaultPresetId||null,cardBindings:{...defaults.value?.value.cardBindings}};if(cardId){if(value.cardBindings[cardId]===row.id)delete value.cardBindings[cardId];else value.cardBindings[cardId]=row.id}else value.defaultPresetId=value.defaultPresetId===row.id?null:row.id;const operation=crypto.randomUUID(),expected=defaults.value?.revision||0;try{await vault.commitBundle(operation,[{kind:'settings',id:'settings:prompt-presets',expectedRevision:expected,value}],controller.signal)}catch(e){if(controller.signal.aborted||store.vault!==vault||!vault.unlocked)throw e;const receipt=await vault.receipt(operation),saved=receipt?await vault.read('settings:prompt-presets'):null;if(!saved||saved.revision!==expected+1||canonical(saved.value)!==canonical(value))throw e}await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,vault=store.vault;if(!vault||busy.value)return;busy.value=true;const failures:string[]=[];try{const files=Array.from(input.files||[]);if(files.length>64)throw new Error('一次最多导入 64 个预设');for(const file of files){controller.signal.throwIfAborted();try{if(file.size>2*1024*1024)throw new Error('预设文件超过 2 MiB');const preset=importPreset(await file.text());await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:'prompt-preset:'+crypto.randomUUID(),expectedRevision:0,value:{assetType:'prompt-preset',name:preset.name,preset}}],controller.signal)}catch(e){if(controller.signal.aborted)throw e;failures.push(file.name+'：'+(e as Error).message)}}await load();error.value=failures.join('；')}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
function download(row:Document<PresetAsset>){try{const url=URL.createObjectURL(new Blob([exportPreset(row.value.preset)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=row.value.name+'.preset.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=(e as Error).message}}
onMounted(()=>void load().catch(e=>error.value=(e as Error).message));onUnmounted(()=>{disposed=true;controller.abort()})
</script>
<template><section><div class="final-page-heading"><div class="final-heading-copy"><span class="final-eyebrow">PROMPT PRESETS</span><h1>{{editing?editing.name:'提示预设'}}</h1></div><div class="final-page-actions"><button v-if="editing" @click="epoch++;editing=null"><ArrowLeft :size="18"/>返回</button><button v-else class="final-primary" @click="edit()"><Plus :size="18"/>新建</button></div></div><p v-if="error" role="alert" class="final-error">{{error}}</p><form v-if="editing" class="final-card-form" @submit.prevent="save"><label>预设名称<input v-model="editing.name" maxlength="200" required></label><label class="final-check"><input v-model="editing.enabled" type="checkbox">启用</label><article v-for="(slot,index) in editing.slots" :key="slot.id" class="final-import-panel"><div class="final-grid-actions"><label class="final-check"><input v-model="slot.enabled" type="checkbox">{{slot.name}}</label><button type="button" class="final-icon-button" :aria-label="'上移'+slot.name" :disabled="index===0" @click="move(index,-1)"><ChevronUp :size="18"/></button><button type="button" class="final-icon-button" :aria-label="'下移'+slot.name" :disabled="index===editing.slots.length-1" @click="move(index,1)"><ChevronDown :size="18"/></button></div><label>内容来源<select v-model="slot.source"><option v-for="source in promptSlots" :key="source" :value="source">{{labels[source]}}</option></select></label><template v-if="slot.source==='custom'"><label>槽名称<input v-model="slot.name" maxlength="200"></label><label>消息角色<select v-model="slot.role"><option value="system">系统</option><option value="user">用户</option><option value="assistant">角色</option></select></label><label>提示内容<textarea v-model="slot.text" rows="4" maxlength="20000"></textarea></label><button type="button" @click="editing.slots.splice(index,1)">移除此槽</button></template></article><button type="button" :disabled="editing.slots.length>=32" @click="add">添加提示槽</button><button class="final-primary" :disabled="busy">保存预设</button><details v-if="editing.source"><summary>保留的原始格式</summary><pre class="final-task-prose">{{editing.source}}</pre></details></form>
<template v-else><div class="final-page-actions"><RouterLink to="/local/characters" class="final-text-link">返回角色</RouterLink><RouterLink to="/local/lorebooks" class="final-text-link">世界书</RouterLink><RouterLink to="/local/tavern/regex" class="final-text-link">正则</RouterLink></div><label class="final-import-panel">导入提示预设<input type="file" accept=".json" multiple :disabled="busy" @change="upload"></label><label v-if="rows.length" class="final-search">搜索预设<input v-model="search" type="search"></label><div v-if="!rows.length" class="final-empty"><SlidersHorizontal :size="40"/><h2>安排每一段提示的位置</h2><button class="final-primary" @click="edit()">创建预设</button></div><div class="final-collection-grid"><article v-for="row in visible" :key="row.id" class="final-character-card"><SlidersHorizontal :size="28"/><h2>{{row.value.name}}</h2><small>{{row.value.preset.slots.filter(slot=>slot.enabled).length}} 个槽 · 版本 {{row.revision}}</small><div class="final-grid-actions"><button @click="edit(row)">编辑</button><button class="final-icon-button" :aria-label="'导出预设'+row.value.name" @click="download(row)"><Download :size="18"/></button></div><button :disabled="busy||!row.value.preset.enabled" :aria-pressed="defaults?.value.defaultPresetId===row.id" @click="bind(row)">{{defaults?.value.defaultPresetId===row.id?'取消全局预设':'设为全局预设'}}</button><label v-if="cards.length">角色专用<select aria-label="预设角色专用" :disabled="busy||!row.value.preset.enabled" @change="bind(row,($event.target as HTMLSelectElement).value);($event.target as HTMLSelectElement).value=''"><option value="">选择或取消绑定</option><option v-for="card in cards" :key="card.id" :value="card.id">{{card.value.name}}{{defaults?.value.cardBindings[card.id]===row.id?' · 已绑定':''}}</option></select></label></article></div></template></section></template>
